@rule
def advance(phase):
    if phase < 183:
        phase = phase + 1


@system
def BitfieldDecodePipelineSystem():  # noqa: N802
    phase: bits[16] = 0
    frame = stimulus(phase)
    packet = DecodeItem(
        word=frame.input_word,
        opcode=frame.input_opcode,
        opcode_rd=frame.input_opcode_rd,
        immediate=frame.input_immediate,
        mode=frame.input_mode,
        rd=frame.input_rd,
        low25=frame.input_low25,
        updated=frame.input_updated,
    )
    dut = BitfieldDecodePipeline(frame.valid, packet, frame.take)

    @rule
    def check():
        assert (
            dut.ready == frame.expected_ready
        ), "bitfield_decode_pipeline input capacity"
        assert (
            dut.valid == frame.expected_valid
        ), "bitfield_decode_pipeline result availability"
        assert (
            dut.data.word == frame.expected_data_word
        ), "bitfield_decode_pipeline word old-state check"
        assert (
            dut.data.opcode == frame.expected_data_opcode
        ), "bitfield_decode_pipeline opcode old-state check"
        assert (
            dut.data.opcode_rd == frame.expected_data_opcode_rd
        ), "bitfield_decode_pipeline opcode_rd old-state check"
        assert (
            dut.data.immediate == frame.expected_data_immediate
        ), "bitfield_decode_pipeline immediate old-state check"
        assert (
            dut.data.mode == frame.expected_data_mode
        ), "bitfield_decode_pipeline mode old-state check"
        assert (
            dut.data.rd == frame.expected_data_rd
        ), "bitfield_decode_pipeline rd old-state check"
        assert (
            dut.data.low25 == frame.expected_data_low25
        ), "bitfield_decode_pipeline low25 old-state check"
        assert (
            dut.data.updated == frame.expected_data_updated
        ), "bitfield_decode_pipeline updated old-state check"
        log("info", "phase", phase)
        log("info", "ready", dut.ready)
        log("info", "valid", dut.valid)
        log("info", "word", dut.data.word)
        log("info", "opcode", dut.data.opcode)
        log("info", "opcode_rd", dut.data.opcode_rd)
        log("info", "immediate", dut.data.immediate)
        log("info", "mode", dut.data.mode)
        log("info", "rd", dut.data.rd)
        log("info", "low25", dut.data.low25)
        log("info", "updated", dut.data.updated)

    advance(phase)
    check()
